const input = Array.isArray($json) ? $json : [$json];
return input.map((deal) => {
  const daysSinceTrigger = Number(deal.daysSinceTrigger ?? 0);
  let cadence;
  if (daysSinceTrigger === 0) cadence = 'D0-immediate';
  else if (daysSinceTrigger >= 2 && daysSinceTrigger < 5) cadence = 'D2-reminder';
  else if (daysSinceTrigger >= 5 && daysSinceTrigger < 7) cadence = 'D5-final';
  else if (daysSinceTrigger >= 7) cadence = 'mark-stale';
  else cadence = 'wait';
  const messageBody = {
    'D0-immediate': 'Thanks for reaching out — sharing the savings calculator + a short overview of how presort works.',
    'D2-reminder': 'Wanted to make sure the savings calculator landed. Happy to walk through it on a 15-min call.',
    'D5-final': 'Last note from me — if the timing is wrong, no problem. Reply STOP to opt out, or pick a time at the link.',
    'mark-stale': null,
    wait: null
  };
const lostReason = cadence === 'mark-stale' ? (deal.lostReason ?? 'no-response') : null;
  return { json: { ...deal, cadence, messageBody: messageBody[cadence], lostReason, nextAction: cadence === 'mark-stale' ? 'CRM stage = closed-lost; tag lostReason' : cadence === 'wait' ? 'No message today.' : 'Send approved Resend template.' } };
});
